#!/usr/bin/env node
// Assert this repo's docs still agree with each other and with the code.
//
// Generated by seam 0.2.0. **Do not edit this file.** Every repo-specific knob lives
// in `.seam/config.json` and is read at run time, so regenerating is always safe — and a knob
// edited into this script is a knob the next regeneration silently drops. To add an assertion
// this repo needs and seam does not have, put it in `.seam/assertions/*.mjs`; those are
// discovered here and never overwritten.
//
// No dependencies, no network, deterministic. Run it:
//
//     node scripts/check_docs.mjs                   # check
//     node scripts/check_docs.mjs --write-baseline  # record today's violations as the baseline
//
// Exit 0: no violations outside the baseline. Exit 1: violations, listed on stderr.
//
// This is a line-for-line mirror of the Python emission. The two are compared on every fixture
// by the test suite, because "a repo can switch languages without changing what is enforced" is
// only true if it is checked.

import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync, statSync, realpathSync } from "node:fs";
import { join, dirname, basename, relative, resolve, sep } from "node:path";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { fileURLToPath, pathToFileURL } from "node:url";

const SEAM_VERSION = "0.2.0";
const CONFIG_PATH = ".seam/config.json";
// Beside the config, and fixed: it is provenance about that file, written by the same run.
const PROVENANCE_PATH = ".seam/provenance.json";

let ROOT = dirname(fileURLToPath(import.meta.url));
while (!existsSync(join(ROOT, CONFIG_PATH)) && dirname(ROOT) !== ROOT) ROOT = dirname(ROOT);

const LAYER_NAMES = { 1: "Artifact", 2: "Current", 3: "Decisions", 4: "Intent", 5: "Seam", 6: "Ledger" };

const MARK_START = "<!-- seam:sources-of-truth start -->";
const MARK_END = "<!-- seam:sources-of-truth end -->";

// `~~struck~~` is where a FORMER truth legitimately lives: the convention that lets a reader see
// why a line changed. Blanked for the assertions about vocabulary, keeping offsets so the line
// numbers stay true. Bounded to a span that does not cross a blank line, because an unbalanced
// `~~` would otherwise pair with the next one paragraphs away and silently swallow the text
// between — a check that stops checking rather than one that fails.
const STRUCK_RE = /~~(?:[^~\n]|\n(?!\n))*?~~/g;

const withoutStruck = (text) => text.replace(STRUCK_RE, (m) => m.replace(/[^\n]/g, " "));

function lineOf(text, index) {
  let n = 1;
  for (let i = 0; i < index && i < text.length; i++) if (text[i] === "\n") n++;
  return n;
}

// Every primitive below exists because this language's own built-in disagrees with the Python
// emission's, and a repo is promised that the choice of checker language does not change what is
// enforced.

const ASCII_WS = " \t\r\n\f\v";
const ASCII_WS_RE = /^[ \t\r\n\f\v]+|[ \t\r\n\f\v]+$/g;

/** `s` without leading or trailing ASCII whitespace.
 *
 *  Not `trim()`, and the Python emission does not use `strip()`: `strip()` takes U+0085 and
 *  `trim()` does not, `trim()` takes U+FEFF and `strip()` does not. So a padded table cell, a
 *  heading or a citation was read one way here and another way there. */
const stripWs = (s) => s.replace(ASCII_WS_RE, "");

/** `s` split on runs of ASCII whitespace, with no empty pieces. `/\s+/` splits on one set and
 *  Python's `str.split()` on another; this is the one both can agree on. */
const splitWs = (s) => s.split(/[ \t\r\n\f\v]+/).filter(Boolean);

/** Whether `ch` is an ASCII letter or digit — what both checkers mean by a word character.
 *  Python's `str.isalnum()` is Unicode-aware and this is not, so a heading or a citation ending
 *  in a non-ASCII letter was a word boundary on one side and not on the other. */
const alnum = (ch) => ch !== undefined && ch !== "" && /^[a-z0-9]$/i.test(ch);

/** `word` as a number when it is a run of ASCII digits, else undefined.
 *
 *  Python's `str.isdigit()` is Unicode-aware and `int()` does not agree with it: `'٣'.isdigit()`
 *  is True and `int('٣')` is 3, where `/^\d+$/` here is false — a count compared on one side and
 *  skipped on the other — while `'²'.isdigit()` is True and `int('²')` raises, so the Python
 *  checker died where this one skipped. The same reason `isalnum()` needed `alnum`. */
const asciiInt = (word) => (/^[0-9]+$/.test(word) ? Number(word) : undefined);

/** Two strings in CODE POINT order, which is how Python compares them.
 *
 *  `localeCompare` is a collation: it puts `alpha.md` before `Zeta.md` and Python puts it after,
 *  so the two checkers printed the same findings in different orders. `<` on a JS string compares
 *  UTF-16 code units, which disagrees with Python above the BMP, so the comparison walks code
 *  points. */
function cmp(a, b) {
  if (a === b) return 0;
  const x = [...a];
  const y = [...b];
  const n = Math.min(x.length, y.length);
  for (let i = 0; i < n; i++) {
    const p = x[i].codePointAt(0);
    const q = y[i].codePointAt(0);
    if (p !== q) return p < q ? -1 : 1;
  }
  return x.length - y.length;
}

/** A repo file as text, read the way the Python emission reads one.
 *
 *  Line endings are normalised because `Path.read_text()` is universal-newline and never sees a
 *  `\r`: without this, a CRLF plan had no sections at all on this side — the per-line heading
 *  regex cannot match a line ending in `\r`, because `.` excludes it — so Node took the silent
 *  branch and exited 0 where Python reported the defect. An invalid byte is U+FFFD here and was
 *  an exception there, which is the other half of the same read. */
const readText = (abs) => readFileSync(abs, "utf8").replace(/\r\n?/g, "\n");

function globRe(pattern) {
  let out = "";
  let i = 0;
  while (i < pattern.length) {
    if (pattern.startsWith("**/", i)) { out += "(?:.*/)?"; i += 3; }
    else if (pattern[i] === "*") { out += "[^/]*"; i += 1; }
    else if (pattern[i] === "?") { out += "[^/]"; i += 1; }
    else { out += pattern[i].replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); i += 1; }
  }
  // The `s` flag so `.` in the `**/` expansion is any character: without it `.` excludes `\r`,
  // U+2028 and U+2029 here and only `\n` in Python, so a path carrying one was inside the glob
  // there and outside it here. `$` with no `m` flag is already the end of the string, which is
  // what Python's `\Z` is for.
  return new RegExp("^" + out + "$", "s");
}

const SKIP = new Set([".git", "node_modules", "dist", "build", ".next", "vendor", "__pycache__",
  ".venv", "venv", "target", ".turbo", "coverage"]);

/** Every file in the repo, skipping nested checkouts and build output. */
function allFiles(root, dir = root, out = []) {
  let entries;
  try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return out; }
  const names = entries.map((e) => e.name);
  if (dir !== root && names.includes(".git")) return out;
  for (const name of names.slice().sort(cmp)) {
    const e = entries.find((x) => x.name === name);
    if (e.isSymbolicLink()) continue;
    const abs = join(dir, name);
    if (e.isDirectory()) {
      if (SKIP.has(name)) continue;
      allFiles(root, abs, out);
    } else if (e.isFile()) {
      out.push(relative(root, abs).split(sep).join("/"));
    }
  }
  return out;
}

/** Files matching a path glob, from the same walk the rest of the checker uses. */
function globFiles(root, pattern) {
  const rx = globRe(pattern);
  return allFiles(root).filter((f) => rx.test(f)).sort(cmp);
}

/** Every markdown file under docs/ plus every one at the repo root. */
function walkMd(root) {
  return allFiles(root)
    .filter((f) => f.endsWith(".md") && (f.startsWith("docs/") || !f.includes("/")))
    .sort(cmp);
}

// ── Markdown reading ─────────────────────────────────────────────────────────

const FENCE_RE = /^[ \t]*(?:```|~~~)/;

/**
 * `text` with every fenced block blanked, keeping the line count so offsets stay true.
 *
 * A `## Heading` written INSIDE a fence is a heading being SHOWN, not declared — and it was
 * becoming a real anchor, so A2 passed a citation naming a section no human can find. The toggle
 * is the one `sectionSpan` and `tableRows` already use: a marker at any indentation opens or
 * closes a block, and an unterminated one runs to the end of the text. That is stricter than a
 * renderer, which reads a four-space-indented marker as literal text, and it is deliberate:
 * three readers of a fence in one file that disagreed would be the drift this whole layer is
 * against.
 */
function withoutFences(text) {
  let fenced = false;
  return text.split("\n").map((line) => {
    if (FENCE_RE.test(line)) { fenced = !fenced; return ""; }
    return fenced ? "" : line;
  }).join("\n");
}

function headings(text) {
  const out = [];
  for (const m of withoutFences(text).matchAll(/^#{1,6}[ \t]+(.*)$/gm)) {
    const h = stripWs(m[1].replaceAll("~~", "").replaceAll("**", "").replaceAll("*", "")
      .replaceAll("`", ""));
    if (h) out.push(h);
  }
  return out;
}

/** Every name a section of this file can legitimately be cited by. */
function anchors(text) {
  const out = new Set();
  for (const h of headings(text)) {
    out.add(h.toLowerCase());
    // Split on a comma as well as an em dash: "API, and what it refuses" is cited as
    // § API, and an em-dash-only split missed that shape repeatedly on a real repo.
    //
    // Only the FIRST clause gets leading-word expansion. Expanding the tail clauses too fed
    // one-word anchors like `and` and `a` into the set — from headings written "Checks, and what
    // each one does" or "Pipeline, a note on scoring" — and since a citation matches any anchor
    // it starts with on a word boundary, A2 then silently passed citations to sections that do
    // not exist. A check that stops checking is worse than one that fails.
    const clauses = h.split(/ — |, /).map(stripWs).filter(Boolean);
    clauses.forEach((c, i) => {
      out.add(c.toLowerCase());
      if (i) return;
      const words = splitWs(c.toLowerCase());
      for (let k = 1; k <= words.length; k++) out.add(words.slice(0, k).join(" "));
    });
  }
  return out;
}

function citesSection(anchorSet, cited) {
  const low = splitWs(cited).join(" ").toLowerCase().replace(/\)+$/, "");
  for (const a of [...anchorSet].sort((x, y) => y.length - x.length)) {
    if (low.startsWith(a) && (low.length === a.length || !alnum(low[a.length]))) {
      return true;
    }
  }
  return false;
}

/**
 * The lines under the heading called `name`, to the next heading at the same level or above, as
 * `[body, line]` — where `line` is the 1-based line the first of them is on. Null when there is
 * no such heading, which callers report rather than treat as empty.
 *
 * The line comes from the scan and not from looking the body up afterwards. `text.indexOf(body)`
 * and `split("\n").indexOf(firstLine)` are lookups by CONTENT: a section body's first line is
 * usually blank, so `indexOf("")` returned the first blank line in the whole file, and a plan
 * that quoted its own units table sent the search into the quotation. Every A8 finding named a
 * line about a dozen rows above the row it was about.
 */
function sectionSpan(text, name) {
  const lines = text.split("\n");
  let start = null;
  let startLevel = 0;
  const low = name.toLowerCase();
  let fenced = false;
  for (let i = 0; i < lines.length; i++) {
    // A heading inside a fenced block is a QUOTE of a section, not that section. A doc that shows
    // a template inside ```markdown had its example read as the real thing, so the assertion
    // measured the placeholder row in the example rather than the table below it.
    if (FENCE_RE.test(lines[i])) { fenced = !fenced; continue; }
    if (fenced) continue;
    // Levels 2 to 6: a `#` heading is the document's title, not a section of it. Without that
    // bound, `§ Checks` in a file called "# Checks" matched the title, whose body is the
    // whole file — so a renamed section still compared something and passed.
    const m = lines[i].match(/^(#{2,6})[ \t]+(.*)$/);
    if (!m) continue;
    const clean = stripWs(m[2].replaceAll("~~", "").replaceAll("**", "").replaceAll("*", ""))
      .toLowerCase();
    if (start === null) {
      // The same rule citations use: the heading begins with the cited name, ending on a word
      // boundary — "The issues" names "The issues, in the order they can be built".
      if (clean.startsWith(low) && (clean.length === low.length || !alnum(clean[low.length]))) {
        start = i + 1;
        startLevel = m[1].length;
      }
      continue;
    }
    if (m[1].length <= startLevel) return [lines.slice(start, i).join("\n"), start + 1];
  }
  return start === null ? null : [lines.slice(start).join("\n"), start + 1];
}

/** `sectionSpan`'s body alone, for the callers that do not report a line inside it. */
function sectionBody(text, name) {
  const span = sectionSpan(text, name);
  return span === null ? null : span[0];
}

/**
 * The cells of a markdown table row, or null when the line is not one. A8 and A14 read their
 * tables through this and nothing else.
 *
 * At most one pipe is dropped at each end, and only ASCII whitespace is trimmed. Both are on
 * purpose: the other checker has to read the same row the same way, and each language's own
 * strip has a different idea of both — Python's `strip("|")` takes every pipe, and `trim()` and
 * `strip()` disagree about U+FEFF and U+0085.
 */
function tableCells(line) {
  const t = stripWs(line);
  if (!t.startsWith("|")) return null;
  return t.slice(1).replace(/\|$/, "").split("|").map(stripWs);
}

/**
 * Every table row in a section body, as `[index, cells]`, **skipping fenced blocks**.
 *
 * A doc that QUOTES a table — a plan showing the template it was written from — has rows in its
 * body that are an example and not a row. Measured on this repo's own plan: `§ The units`
 * reported "unit 1 has no test path" from a ```markdown block eighty lines below the real table.
 * A8 and A14 read their tables through here and nothing else, so the two agree about what a row
 * is. `sectionBody` skips a fenced heading for the same reason.
 */
function tableRows(body) {
  const out = [];
  let fenced = false;
  const lines = body.split("\n");
  for (let i = 0; i < lines.length; i++) {
    if (FENCE_RE.test(lines[i])) { fenced = !fenced; continue; }
    if (fenced) continue;
    const cells = tableCells(lines[i]);
    if (cells !== null) out.push([i, cells]);
  }
  return out;
}

// ── The assertion pattern ────────────────────────────────────────────────────

const DEFAULT_ASSERTION_PATTERN =
  String.raw`\bassert(?:[_A-Z]\w*)?\b|\bexpect(?:[_A-Z]\w*)?\b|\b(?:ASSERT|EXPECT)_\w+\b`;

// What a backslash may be followed by: a class or control escape, or any non-alphanumeric
// printable ASCII character, which both engines read as that character. A letter or a digit is
// refused — `\B` matches an empty string in Node and nowhere in one in Python, and `\q` is an
// error in Python and a literal in Node. `\b` is an anchor and is handled where it can appear.
const ESCAPE_LETTERS = "wWdDsSnrt";
const ESCAPE_PUNCT_RE = /^[\x20-\x2f\x3a-\x40\x5b-\x60\x7b-\x7e]$/;
const escapable = (d) => d !== "" && (ESCAPE_LETTERS.includes(d) || ESCAPE_PUNCT_RE.test(d));

/**
 * Why `p` is not a pattern both emitted checkers read the same way, or null when it is.
 *
 * `assertions.A14.assertion_pattern` is run by a Node engine here and a Python one in the other
 * checker, and they disagree about plenty: inline flags, named groups, a range out of a class
 * escape, possessive quantifiers, `{,n}`. A checker that ran whatever its own engine accepted
 * would pass a repo in one language and fail it in the other, so a pattern is held to a subset
 * both read identically — literals, `.`, `^` `$` `|`, `(…)` and `(?:…)`, simple `[…]` classes,
 * the escapes above, `\b`, and `* + ? {n} {n,} {n,m}` with an optional lazy `?`. Printable
 * ASCII only. It is a scanner and not a regex because a regex cannot count brackets.
 */
function portableRegex(p) {
  if (p === "") return "it is empty";
  const bad = (k) => `character ${k + 1} is outside the subset both checkers read the same way`;
  const odd = p.search(/[^\x20-\x7e]/);
  if (odd !== -1) return bad(odd);
  const n = p.length;
  let i = 0;
  let depth = 0;
  let prev = null;                  // what a quantifier may follow: "atom", or nothing
  while (i < n) {
    const c = p[i];
    if (c === "\\") {
      const d = p.charAt(i + 1);
      if (d === "b") prev = "anchor";
      else if (escapable(d)) prev = "atom";
      else return bad(i);
      i += 2;
    } else if (c === "[") {
      let j = i + 1;
      if (p.charAt(j) === "^") j += 1;
      let items = 0;
      for (;;) {
        const k = p.charAt(j);
        if (k === "") return bad(i);                          // never closed
        if (k === "]") {
          if (items === 0) return bad(j);                     // empty: engines disagree
          j += 1;
          break;
        }
        if (k === "\\") {
          const d = p.charAt(j + 1);
          if (!escapable(d)) return bad(j);
          j += 2;
        } else if (k === "[" || k === "&" || k === "~" || k === "|") {
          return bad(j);                                      // Python warns these may change
        } else if (k === "-") {
          // A hyphen is a literal only at either end of the class; anywhere else it is a range
          // operator, and what a range from a class escape means differs by engine.
          if (items !== 0 && p.charAt(j + 1) !== "]") return bad(j);
          j += 1;
        } else if (p.charAt(j + 1) === "-" && p.charAt(j + 2) !== "]" && p.charAt(j + 2) !== "") {
          const hi = p.charAt(j + 2);
          if ("\\[]-&~|".includes(hi) || hi < k) return bad(j);
          j += 3;
        } else {
          j += 1;
        }
        items += 1;
      }
      prev = "atom";
      i = j;
    } else if (c === "(") {
      if (p.charAt(i + 1) === "?") {
        if (p.charAt(i + 2) !== ":") return bad(i);           // lookaround, flags, names
        i += 3;
      } else {
        i += 1;
      }
      depth += 1;
      prev = null;
    } else if (c === ")") {
      if (depth === 0) return bad(i);
      depth -= 1;
      prev = "atom";
      i += 1;
    } else if (c === "|") {
      prev = null;
      i += 1;
    } else if (c === "^" || c === "$") {
      prev = "anchor";
      i += 1;
    } else if (c === "*" || c === "+" || c === "?") {
      if (prev !== "atom") return bad(i);
      i += 1;
      if (p.charAt(i) === "?") i += 1;                        // lazy; a second quantifier is refused
      prev = "quantified";
    } else if (c === "{") {
      const m = prev === "atom" ? p.slice(i).match(/^\{(\d{1,3})(?:,(\d{0,3}))?\}/) : null;
      if (!m || (m[2] && Number(m[2]) < Number(m[1]))) return bad(i);
      i += m[0].length;
      if (p.charAt(i) === "?") i += 1;
      prev = "quantified";
    } else if (c === "}" || c === "]") {
      return bad(i);
    } else {
      prev = "atom";                                          // `.` and every plain literal
      i += 1;
    }
  }
  return depth === 0 ? null : "a group is never closed";
}

const MD_CITE_RE = /`([\w./@-]+\.md)`/g;
// A `|` ends a section name: it is a table cell boundary and never part of a heading.
const TOKEN_RE = /`([^`\n]+)`|(?<![`\w./-])([\w./-]+\.md)(?![\w.-])|§[ \t\n]*([A-Za-z][^.;:—(*`§|\n]*)/g;
// Written out rather than `\s`: the three whitespace sets — this engine's `\s`, Python's
// Unicode `\s` and its ASCII one — are three different sets, and only an explicit class is the
// same on both sides.
const ADJACENT_RE = /^[ \t\r\n\f\v,*]{0,4}$/;
const CONNECTOR_RE = /^[ \t\r\n\f\v,]*(?:and|or)?[ \t\r\n\f\v,]*$/;

function resolveMd(root, frm, cited) {
  if (existsSync(join(root, cited))) return cited;
  const beside = resolve(dirname(join(root, frm)), cited);
  const rel = relative(root, beside).split(sep).join("/");
  return existsSync(beside) ? rel : null;
}

// What A12 freezes: a RECORD, not the file that indexes it. An index grows by design — adding a
// version means appending a row — and a "current" file is replaced wholesale when a new version
// lands. Freezing either makes the layer unusable, which is the opposite of enforcing its edit
// rule. A template is a form, not a record, so it is not frozen either.
const NOT_A_RECORD = new Set(["README.md", "template.md", "PRD-current.md", "index.md"]);

const frozenRecord = (path) => !NOT_A_RECORD.has(basename(path));

/** The default branch as this checkout has it: `<branch>` if that resolves to a commit, else
 *  `origin/<branch>`, else null. A local branch ref is not a given: a pull request's CI checkout
 *  is a detached HEAD whose only copy of the default branch is `origin/<branch>`, so a check that
 *  needs a local ref to exist would red every adopting repo on its first pull request. A12 and
 *  A15 both read the default branch, so both resolve it here and nowhere else. */
function resolveDefaultBranch(branch) {
  for (const cand of [branch, `origin/${branch}`]) {
    try {
      execFileSync("git", ["rev-parse", "--verify", "--quiet", `${cand}^{commit}`],
        { cwd: ROOT, stdio: ["ignore", "ignore", "ignore"] });
      return cand;
    } catch { /* try the next form */ }
  }
  return null;
}

// The one field a MADR record may change after it is on the default branch. The method's own rule
// for a reversal is that the OLD record gains `superseded by NNNN`, and A13 requires that a
// superseded record names a successor that exists — both asked of the same bytes, so byte-equality
// alone made them unsatisfiable the first time a repo reversed a decision. Its substance stays
// frozen; its status is metadata about supersession. Nothing wider than this one line, and not
// arbitrary content on it either: the new line is a short run of plain characters. No \r inside
// it, because a markdown renderer shows a lone CR as a line break, so one could smuggle in new
// paragraphs while the \n line count stayed equal; the single \r that ends a CRLF line is the
// terminator and is allowed. What a status may SAY is A13's question, so this is one bound and
// not a vocabulary.
const STATUS_LINE = /^\*\*Status:\*\*/;
const STATUS_VALUE = /^\*\*Status:\*\*[A-Za-z0-9_ \t.,;:()'\/#-]{0,120}\r?$/;

/** True when `was` and `now` have the same number of lines and differ only on lines that open
 *  `**Status:**` in `was` and are a short plain `**Status:**` line in `now`. Compared as bytes
 *  (latin1 maps one byte to one char), never as decoded text, so it cannot read invalid UTF-8
 *  differently from the Python checker. */
function differsOnlyInStatusLines(was, now) {
  const a = was.toString("latin1").split("\n");
  const b = now.toString("latin1").split("\n");
  if (a.length !== b.length) return false;
  return a.every((line, i) => line === b[i] || (STATUS_LINE.test(line) && STATUS_VALUE.test(b[i])));
}

/** Every `*.md` path this file claims exists, with its offset.
 *
 *  A backticked path that is the TEXT of a markdown link is a label, not a citation: in
 *  ``[`api.md`](.claude/rules/api.md)`` the link target is the claim and the label is how it
 *  reads. Measured on a repo nothing was tuned against — a README listing eight rules that way
 *  reported eight dangling citations, every one of them wrong, while the targets all resolved. */
function mdCitations(root, frm, text) {
  const out = [];
  const linkedSpans = [];
  for (const m of text.matchAll(/\[([^\]\n]*)\]\(([^) \t\r\n\f\v]+)\)/g)) {
    const labelStart = m.index + 1;
    linkedSpans.push([labelStart, labelStart + m[1].length]);
    const target = m[2].split("#")[0];
    if (target.endsWith(".md")) out.push([target, m.index]);
  }
  for (const m of text.matchAll(MD_CITE_RE)) {
    const s = m.index + 1;
    const e = s + m[1].length;
    if (linkedSpans.some(([a, b]) => a <= s && e <= b)) continue;
    out.push([m[1], m.index]);
  }
  return out;
}

// ── The sources-of-truth table ───────────────────────────────────────────────

function readTable(text) {
  const start = text.indexOf(MARK_START);
  const end = text.indexOf(MARK_END);
  const scoped = start !== -1 && end > start;
  const body = scoped ? text.slice(start, end) : text;
  const offset = scoped ? start : 0;
  const rows = [];
  for (const m of body.matchAll(/^\|(.*)\|[ \t]*$/gm)) {
    // The same splitter A8 and A14 read a row with. Its own split-and-trim disagreed with
    // Python's about U+0085 and U+FEFF, so a padded first cell was a row in one checker and not
    // in the other — and a doc with no row is A10's loudest finding.
    const cells = tableCells(m[0]);
    // `cells &&`, because the splitter returns null for a line that is not a row at all — which
    // this regex cannot produce, and the Python emission's `if cells` already tolerated.
    const doc = cells && cells.length ? cells[0].match(/^`([^`]+)`$/) : null;
    if (!doc) continue;
    let layer = null;
    if (cells.length > 1) {
      const lm = cells[1].match(/^(\d)\b/);
      if (lm) layer = Number(lm[1]);
    }
    rows.push({
      doc: doc[1],
      layer,
      owns: cells.length > 2 ? cells[2] : "",
      // The backticks at the ENDS only, which is what Python's `strip("`")` takes: removing
      // every one of them made a cell naming two paths two different finding texts, and a
      // finding's text is part of its baseline key.
      enforces: cells.length > 3 ? cells[3].replace(/^`+|`+$/g, "") : "",
      line: lineOf(text, offset + m.index),
    });
  }
  return rows;
}

// ── Artifact parsing ─────────────────────────────────────────────────────────

function sqlTables(sql) {
  const out = {};
  for (const m of sql.matchAll(
      /create table (?:if not exists )?(\w+)[ \t\r\n\f\v]*\(([\s\S]*?)\n\);/gi)) {
    const cols = new Set([...m[2].matchAll(/^[ \t\r\n\f\v]{2,}(\w+)[ \t\r\n\f\v]/gm)]
      .map((c) => c[1]));
    out[m[1]] = cols;
  }
  return out;
}

function sqlEnum(sql, name) {
  const ws = "[ \\t\\r\\n\\f\\v]";
  const rx = new RegExp("create type" + ws + "+" + name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
    + ws + "+as enum" + ws + "*\\(([\\s\\S]*?)\\);", "i");
  const m = sql.match(rx);
  return m ? new Set([...m[1].matchAll(/'([^']+)'/g)].map((x) => x[1])) : null;
}

function tsUnions(text) {
  const out = {};
  for (const m of text.matchAll(
      /(?:type|enum)[ \t\r\n\f\v]+(\w+)[ \t\r\n\f\v]*=?[ \t\r\n\f\v]*\{?([^;}]*)[;}]/g)) {
    const members = new Set([...m[2].matchAll(/['"]([\w-]+)['"]/g)].map((x) => x[1]));
    if (members.size) out[m[1]] = members;
  }
  return out;
}

// ── A3: the documented check list against CI ─────────────────────────────────

// Right-hand sides that are not fields: file extensions and hostname endings. A dotted name
// whose right half is one of these is a path or a host, not a reference.
// Deliberately narrow: only endings that cannot plausibly be a column or a union member.
// `html`, `json`, `log`, `env`, `css`, `txt`, `csv`, `xml`, `svg`, `pdf`, `app` and `dev` were all
// in an earlier version of this list and are all plausible field names — a repo documenting
// `pages.html` would have had A4 stay green forever through a rename. Set
// `assertions.A4.not_fields_override` to replace this list outright.
const DEFAULT_NOT_FIELDS = new Set([
  "md", "sql", "yml", "yaml", "toml", "ini", "cfg", "tmpl",
  "py", "pyi", "mjs", "cjs", "jsx", "tsx", "sh", "bash", "zsh", "rb", "rs", "kt", "swift",
  "php", "prisma", "proto", "graphql", "lock", "webp", "ico", "gz", "tgz", "whl",
  "com", "org", "net", "gov", "edu", "il", "uk", "online",
]);

const DEFAULT_TOKEN_RES = [
  "scripts/[\\w.\\-/]+\\.(?:py|sql|mjs|js|ts|sh)",
  "(?:npm|pnpm|yarn|bun) run [\\w:.\\-]+",
  "node --test",
  "(?:^|&&|;|\\|)[ \\t\\r\\n\\f\\v]*(?:pytest|ruff|mypy|eslint|tsc|cargo|go test)\\b",
  "check:[a-z\\-]+",
  "docker build",
  "drop schema public cascade",
];
const TURBO_RE = /turbo run ((?:[a-z]+ )*[a-z]+)/g;

/** Drop shell and YAML comments, keeping a quoted `#` as the content it is. */
function stripComments(text) {
  text = text.replace(/\\\n/g, " ");
  const out = [];
  for (const line of text.split("\n")) {
    let quote = "";
    let cut = null;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (quote) {
        if (ch === quote) quote = "";
      } else if (ch === "'" || ch === '"') {
        quote = ch;
      } else if (ch === "#" && (i === 0 || ASCII_WS.includes(line[i - 1]))) {
        cut = i;
        break;
      }
    }
    out.push(cut === null ? line : line.slice(0, cut));
  }
  return out.join("\n");
}

function checkTokens(text, extra) {
  text = stripComments(text);
  const found = new Set();
  for (const src of [...DEFAULT_TOKEN_RES, ...extra]) {
    for (const m of text.matchAll(new RegExp(src, "gm"))) {
      found.add(m[0].replace(/^[&|; \t\r\n\f\v]+/, ""));
    }
  }
  for (const m of text.matchAll(TURBO_RE)) {
    for (const task of m[1].split(" ")) found.add("turbo:" + task);
  }
  return found;
}

const RUN_KEY_RE = /^[ \t]*(?:-[ \t]+)?(run:)[ \t]*(\|[-+0-9]*)?[ \t]*(.*)$/;

/** Every `run:` payload in a workflow, with the line it starts on. */
function runPayloads(yamlText) {
  const lines = yamlText.split("\n");
  const out = [];
  let i = 0;
  while (i < lines.length) {
    const m = lines[i].match(RUN_KEY_RE);
    if (!m) { i += 1; continue; }
    const col = lines[i].indexOf("run:");
    const body = [m[3]];
    const start = i + 1;
    let j = i + 1;
    while (j < lines.length) {
      const line = lines[j];
      if (stripWs(line) === "") { body.push(""); j += 1; continue; }
      const indent = line.length - line.replace(/^[ \t\r\n\f\v]+/, "").length;
      if (indent <= col) break;
      body.push(line);
      j += 1;
    }
    out.push([start, body.join("\n")]);
    i = j;
  }
  return out;
}

// ── Findings ─────────────────────────────────────────────────────────────────

const finding = (id, file, line, text, message) => ({ id, file, line, text, message });

// Each assertion's own lists, and the keys each entry is indexed by — null for a list of plain
// strings. `plan_glob` is a string OR a list of them, so it is handled beside this.
const ENTRY_LISTS = [
  ["A1", "intent_globs", null, []],
  ["A3", "doc_sections", ["file", "section"], []],
  ["A3", "local_only", null, []],
  ["A3", "ci_only", null, []],
  ["A3", "extra_tokens", null, []],
  ["A4", "artifacts", ["path"], ["parser"]],
  ["A4", "not_fields", null, []],
  ["A4", "not_references", null, []],
  ["A4", "not_fields_override", null, []],
  ["A5", "vocabularies", ["file", "section", "enum"], []],
  ["A6", "retired", ["name"], ["became", "reason"]],
  ["A7", "reversed", ["pattern", "reason"], ["adr"]],
  ["A9", "count_sites", ["pattern", "count_of"], ["file"]],
  ["A15", "impl_globs", null, []],
  ["A15", "test_globs", null, []],
];
const GLOB_OR_LIST = ["A8", "A14"];

/**
 * The first config value no reader below can use, as the message to refuse with — or null.
 *
 * One pass over the shapes, before anything indexes them. A value of the wrong shape was a
 * `TypeError` here and a `KeyError` or an `AttributeError` in the Python emission, so the same
 * malformed config ended two different ways — and an `allow` that is an object rather than a
 * list escaped the refusal below entirely, because `list.length` was `undefined` and the loop
 * body never ran. A traceback is never an acceptable ending for a malformed config: it is a
 * refusal, with the same message and the same exit in both languages.
 *
 * The checks are in a fixed order and assertion ids are sorted, so a config broken in two ways
 * is refused for the same one by both.
 */
function configShapeRefusal(cfg) {
  const isObj = (v) => typeof v === "object" && v !== null && !Array.isArray(v);
  const isList = (v) => Array.isArray(v);
  const isName = (v) => typeof v === "string" && v !== "";
  const checks = [];
  const table = cfg.table ?? {};
  checks.push(["table", isObj(table), "an object",
    "it names the file that hosts the sources-of-truth table"]);
  if (isObj(table)) {
    checks.push(["table.file", isName(table.file), "a path",
      "every doc's layer is recorded in that file, so without it there is nothing to hold a doc "
      + "to"]);
  }
  const docsRows = cfg.docs ?? [];
  checks.push(["docs", isList(docsRows), "a list", "A11 reads it row by row against the table"]);
  if (isList(docsRows)) {
    docsRows.forEach((d, i) => {
      checks.push([`docs[${i}]`, isObj(d), "an object", "a docs row is a path and the layer it is on"]);
      if (isObj(d)) {
        checks.push([`docs[${i}].path`, isName(d.path), "a path",
          "a row naming no doc says nothing about one"]);
      }
    });
  }
  const lb = cfg.load_bearing ?? [];
  checks.push(["load_bearing", isList(lb), "a list", "A11 reads it as path globs"]);
  if (isList(lb)) {
    lb.forEach((g, i) => checks.push([`load_bearing[${i}]`, typeof g === "string", "a string",
      "each entry is a path glob"]));
  }
  /** A list the readers walk: `keys` null for a list of strings, else the keys each entry is
   *  indexed by. */
  const entryList = (where, value, keys, reader, optional = []) => {
    checks.push([where, isList(value), "a list", `${reader} reads it as a list`]);
    if (!isList(value)) return;
    value.forEach((e, i) => {
      if (keys === null) {
        checks.push([`${where}[${i}]`, typeof e === "string", "a string",
          `${reader} reads every entry of it as a string`]);
        return;
      }
      const named = keys.map((k) => `\`${k}\``).join(", ");
      checks.push([`${where}[${i}]`, isObj(e), "an entry",
        `${reader} reads each entry's ${named}`]);
      if (!isObj(e)) return;
      for (const k of keys) {
        const pathLike = k === "file" || k === "path" || k === "count_of";
        checks.push([`${where}[${i}].${k}`, isName(e[k]),
          pathLike ? "a path" : "a non-empty string", `${reader} indexes the entry by it`]);
      }
      // An optional key still has a shape when it is there: one that is read for its truth is
      // `[]` — true here and FALSE in Python — and one that is interpolated into a finding's
      // message prints differently in the two languages, and that message is part of the
      // finding's baseline key.
      for (const k of optional) {
        if ((e[k] ?? null) === null) continue;
        checks.push([`${where}[${i}].${k}`, typeof e[k] === "string", "a string",
          `${reader} reads it as one when it is there`]);
      }
    });
  };
  entryList("artifacts", cfg.artifacts ?? [], ["path"], "A5");
  for (const [key, sub] of [["adr", ["format", "file", "dir"]], ["prd", ["dir"]],
    ["baseline", ["path"]]]) {
    const value = cfg[key] ?? {};
    checks.push([key, isObj(value), "an object", "it is read key by key"]);
    if (!isObj(value)) continue;
    for (const k of sub) {
      if ((value[k] ?? null) === null) continue;   // absent or null: the reader's default applies
      checks.push([`${key}.${k}`, typeof value[k] === "string", "a string", "it is read as one"]);
    }
  }
  const A = cfg.assertions ?? {};
  checks.push(["assertions", isObj(A), "an object",
    "every assertion's settings live under its id there"]);
  if (isObj(A)) {
    for (const aid of Object.keys(A).sort(cmp)) {
      checks.push([`assertions.${aid}`, isObj(A[aid]), "an object",
        "an assertion's settings are an object with an `enabled` switch"]);
      if (!isObj(A[aid])) continue;
      const conf = A[aid];
      // The switch is read as a truth value, and the two languages disagree about which values
      // are true: `Boolean([])` is true here and `bool([])` is False in Python, so `enabled: []`
      // ran the assertion in one checker and not the other — and the enabled SET is what the
      // provenance precondition compares, so one of them also refused.
      for (const flag of ["enabled", "bare_sections"]) {
        if ((conf[flag] ?? null) === null) continue;
        checks.push([`assertions.${aid}.${flag}`, typeof conf[flag] === "boolean",
          "true or false", "it is read as a switch"]);
      }
      // The list and its entries only: an allow entry's `path` and `reason` have refusals of
      // their own further down, which carry the method's reason for requiring them and are
      // better messages than this pass can give.
      if ((conf.allow ?? null) !== null) {
        const allow = conf.allow;
        checks.push([`assertions.${aid}.allow`, isList(allow), "a list",
          "an allow-list is a list of entries, each naming one path and the reason it will never "
          + "be fixed"]);
        if (isList(allow)) {
          allow.forEach((e, i) => checks.push([`assertions.${aid}.allow[${i}]`, isObj(e),
            "an entry", "an allow-list entry is an object with a `path` and a `reason`"]));
        }
      }
      // Each assertion's own lists, in a fixed order. Their readers index an entry directly —
      // `v.file`, `art.path`, `site.pattern` — which was a `KeyError` in Python and an
      // `undefined` that reached a finding's baseline key here.
      for (const [owner, key, keys, optional] of ENTRY_LISTS) {
        if (owner !== aid || (conf[key] ?? null) === null) continue;
        entryList(`assertions.${aid}.${key}`, conf[key], keys, aid, optional);
      }
      if (GLOB_OR_LIST.includes(aid) && (conf.plan_glob ?? null) !== null) {
        const g = conf.plan_glob;
        if (typeof g === "string") {
          /* one glob, which is the other form this key takes */
        } else if (isList(g)) {
          g.forEach((one, i) => checks.push([`assertions.${aid}.plan_glob[${i}]`,
            typeof one === "string", "a string",
            `${aid} reads every entry of it as a glob`]));
        } else {
          checks.push([`assertions.${aid}.plan_glob`, false, "a string or a list of strings",
            `${aid} reads it as the globs its layer-5 docs match`]);
        }
      }
      if (aid === "A3" && (conf.workflow_glob ?? null) !== null) {
        checks.push(["assertions.A3.workflow_glob", typeof conf.workflow_glob === "string",
          "a string", "A3 reads it as the glob the workflows match"]);
      }
    }
  }
  for (const [where, ok, want, why] of checks) {
    if (ok) continue;
    return `seam: ${CONFIG_PATH} ${where} is not ${want} — ${why}. The answers file is the `
      + `source and this file is its projection, so write it there and regenerate `
      + `(\`seam-init --answers <file> --repo .\`).`;
  }
  return null;
}

const WORDS = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8,
  nine: 9, ten: 10, eleven: 11, twelve: 12 };

async function main() {
  const cfgFile = join(ROOT, CONFIG_PATH);
  if (!existsSync(cfgFile)) {
    process.stderr.write(`seam: no ${CONFIG_PATH} found above `
      + `${realpathSync(dirname(fileURLToPath(import.meta.url)))}\n`);
    return 2;
  }
  // Two refusals, not one, and neither interpolates the engine's own sentence into the line the
  // two languages are held to: `JSON.parse`'s parse error and Python `json`'s are differently
  // worded, and a malformed config has to be one identical message. The detail is printed on a
  // line of its own. The read is separate from the parse because a mode-000 config, or a
  // directory at that path, is a different thing to say — and it tracebacked in Python while
  // this side's catch refused.
  let raw;
  try {
    raw = readText(cfgFile);
  } catch {
    process.stderr.write(`seam: ${CONFIG_PATH} could not be read. It is the file every knob is `
      + `read from, so there is nothing to run — check its permissions, or write it with the `
      + `wizard (\`seam-init --answers <file> --repo .\`).\n`);
    return 2;
  }
  let cfg;
  try {
    cfg = JSON.parse(raw);
  } catch (e) {
    process.stderr.write(`seam: ${CONFIG_PATH} is not readable JSON. Regenerate it with the `
      + `wizard (\`seam-init --answers <file> --repo .\`), which writes it from the answers `
      + `file; the parser's own message is on the next line.\n`);
    process.stderr.write(`seam: the parser said: ${e.message}\n`);
    return 2;
  }
  if (typeof cfg !== "object" || cfg === null || Array.isArray(cfg)) {
    process.stderr.write(`seam: ${CONFIG_PATH} is not an object. The config is what every knob `
      + `is read from, so there is nothing to run — regenerate it with the wizard `
      + `(\`seam-init --answers <file> --repo .\`).\n`);
    return 2;
  }
  const shape = configShapeRefusal(cfg);
  if (shape !== null) {
    process.stderr.write(shape + "\n");
    return 2;
  }
  const A = cfg.assertions ?? {};
  const on = (k) => Boolean(A[k]?.enabled);
  // A JSON null means the key is unset, which is what `??` reads it as — and what the Python
  // emission now reads it as too. Returning the null instead handed a reader a value no reader
  // expects: `[...null]` threw before any assertion could report anything.
  const opt = (k, name, dflt = undefined) => (A[k]?.[name] ?? dflt);

  // A checker that measures nothing cannot be told from one that passed, which is the thing this
  // whole layer exists to prevent. Refuse rather than exit 0.
  const enabledIds = Object.keys(A).filter((k) => A[k]?.enabled);
  const assertionsDir = join(ROOT, ".seam", "assertions");
  if (!enabledIds.length && !(existsSync(assertionsDir) && statSync(assertionsDir).isDirectory())) {
    process.stderr.write(`seam: no assertions are enabled in ${CONFIG_PATH}, and there are none `
      + `in .seam/assertions/ — this checker would measure nothing and exit 0, which cannot be `
      + `told apart from passing. Enable at least one.\n`);
    return 2;
  }

  // ── The integrity precondition ──────────────────────────────────────────
  //
  // A16 compares this config with the answers file it was projected from, and **A16's own switch
  // lives in this config**. Setting `assertions.A16.enabled` to false and editing the config in
  // the same write was therefore silent: the only trace was the assertion count falling by one.
  //
  // So this is not an assertion. An assertion can be switched off, which is the problem. It runs
  // here — before the loop, independent of every switch — and exits 2, because "the comparison
  // could not be trusted" is a different claim from "a doc is wrong".
  //
  // The boundary, stated rather than implied: editing the config AND this record together still
  // defeats it, the same way re-hashing defeats A16. What is closed is the silent single edit.
  let prov = null;
  try {
    prov = JSON.parse(readText(join(ROOT, PROVENANCE_PATH)));
  } catch { /* handled below */ }
  const regenerate = `Write it with the wizard: \`seam-init --answers <file> --repo .\`, which`
    + ` rewrites ${CONFIG_PATH} and this record together.`;
  if (prov === null || typeof prov !== "object" || Array.isArray(prov)) {
    process.stderr.write(`seam: no readable ${PROVENANCE_PATH}, so there is no record of which`
      + ` assertions were enabled when this checker was emitted — and a switch flipped in`
      + ` ${CONFIG_PATH} is a silent change to what is measured, A16's own switch included.`
      + ` ${regenerate}\n`);
    return 2;
  }
  const recorded = prov.assertions_enabled;
  if (!Array.isArray(recorded) || recorded.some((x) => typeof x !== "string")) {
    process.stderr.write(`seam: ${PROVENANCE_PATH} has no \`assertions_enabled\` list, so the`
      + ` enabled set could not be compared with the one on record. An absent list is not "none`
      + ` enabled". ${regenerate}\n`);
    return 2;
  }
  const live = enabledIds.slice().sort(cmp);
  const want = recorded.slice().sort(cmp);
  if (live.join(",") !== want.join(",")) {
    const only = (a, b) => a.filter((x) => !b.includes(x));
    const added = only(live, want);
    const gone = only(want, live);
    process.stderr.write(`seam: ${CONFIG_PATH} does not enable the assertions`
      + ` ${PROVENANCE_PATH} records.`
      + (added.length ? ` Enabled here and not on record: ${added.join(", ")}.` : "")
      + (gone.length ? ` On record and not enabled here: ${gone.join(", ")}.` : "")
      + ` The answers file is the source and the config is its projection, so a switch flipped by`
      + ` hand is a silent change to what this checker measures — which is why this is a refusal`
      + ` and not an assertion. ${regenerate}\n`);
    return 2;
  }

  // An allow-list entry means "this will never be fixed", so the method requires a written
  // reason. Nothing read the field, which made the requirement a sentence.
  //
  // And it requires a PATH, because an exemption that names nothing cannot exempt anything. The
  // three readers of that field disagreed about what a missing one was — a Python `KeyError`, a
  // Node `undefined`, and `"None"` against `""` in the obsolescence message, whose text is part
  // of a finding's baseline key — so it is refused here, once, before anything reads it.
  // The shape of `allow` and of each entry is settled by `configShapeRefusal` above, so what is
  // left here is what the entry SAYS.
  for (const aid of Object.keys(A).sort(cmp)) {
    const list = A[aid]?.allow ?? [];
    for (let i = 0; i < list.length; i++) {
      if (typeof list[i]?.path !== "string" || list[i].path === "") {
        process.stderr.write(`seam: ${CONFIG_PATH} assertions.${aid}.allow[${i}].path is not a `
          + `path. An allow-list entry exempts one path from one assertion, so an entry naming `
          + `none exempts nothing — write the path, or delete the entry.\n`);
        return 2;
      }
      if (!stripWs(String(list[i]?.reason ?? ""))) {
        process.stderr.write(`seam: ${CONFIG_PATH} assertions.${aid}.allow[${i}] exempts `
          + `'${list[i]?.path ?? "<no path>"}' with no reason. An allow-list entry means "this `
          + `will never be fixed" — write why, or use the baseline, which means "not yet".\n`);
        return 2;
      }
    }
  }

  const host = cfg.table.file;
  const docs = walkMd(ROOT);
  const textOf = {};
  for (const d of docs) if (existsSync(join(ROOT, d))) textOf[d] = readText(join(ROOT, d));
  const anchorsOf = {};
  for (const [d, t] of Object.entries(textOf)) anchorsOf[d] = anchors(t);
  const table = readTable(textOf[host] ?? "");
  const findings = [];
  let ran = 0;

  // ── A1. Every `*.md` path cited in backticks resolves. ───────────────────
  if (on("A1")) {
    ran += 1;
    const allowList = opt("A1", "allow", []);
    const allowed = new Set(allowList.map((e) => e.path));
    // Which entries actually suppressed a finding. An allow entry means "this will never be
    // fixed", so one that stopped doing work is a decision about nothing — and worse, it goes on
    // skipping its path, so a citation that starts dangling again is skipped with it.
    const usedAllow = new Set();
    // A doc that describes work NOT YET DONE cites files as intentions, not as claims about the
    // tree: an implementation plan names what it is about to create. Those citations are neither
    // debt (a baseline means "not yet" and they evaporate on landing) nor approvals (an
    // allow-list means "never"), so the doc is what is exempted rather than each path.
    const intent = (opt("A1", "intent_globs", [])).map(globRe);
    for (const d of docs) {
      if (intent.some((rx) => rx.test(d))) continue;
      for (const [cited, at] of mdCitations(ROOT, d, textOf[d])) {
        if (cited.includes("*")) continue;
        if (allowed.has(cited)) {
          // Only a citation that WOULD have been reported earns the entry its place: one that
          // resolves needs no exemption.
          if (resolveMd(ROOT, d, cited) === null) usedAllow.add(cited);
          continue;
        }
        if (resolveMd(ROOT, d, cited) === null) {
          findings.push(finding("A1", d, lineOf(textOf[d], at), cited,
            `cites \`${cited}\`, which is not in the repo — fix or drop the citation, or add it `
            + `to assertions.A1.allow with a reason`));
        }
      }
    }
    // An empty allow-list is not a finding: nothing is exempted, so nothing stopped doing work.
    for (const e of allowList) {
      const p = e.path;                       // a string, or the run was refused above
      if (usedAllow.has(p)) continue;
      const why = p.includes("*")
        ? "a glob, which A1 never consults — a cited path containing `*` names a form and is "
          + "skipped before the allow-list is read, so this entry can exempt nothing"
        : existsSync(join(ROOT, p))
          ? "now in the repo, so every citation of it resolves and needs no exemption"
          : "cited nowhere A1 reads, or cited only where every citation of it resolves";
      findings.push(finding("A1", CONFIG_PATH, 1, p,
        `assertions.A1.allow exempts \`${p}\`, which is ${why}. The entry suppressed nothing on `
        + `this run, and an allow entry means "this will never be fixed" — so it is a decision `
        + `about nothing, and it will go on skipping that path if it starts dangling again. `
        + `Delete it and let A1 answer for the path`));
    }
  }

  // ── A2. Every `§ Section` citation names a heading that exists. ──────────
  if (on("A2")) {
    ran += 1;
    const bareToo = Boolean(opt("A2", "bare_sections", false));
    for (const d of docs) {
      const text = textOf[d];
      let base = 0;
      for (const para of text.split(/\n[ \t]*\n/)) {
        let target = null;
        let targetEnd = -1;
        let shadow = null;
        let shadowEnd = -1;
        for (const m of para.matchAll(TOKEN_RE)) {
          const backticked = m[1];
          const bare = m[2];
          const name = m[3];
          if (backticked !== undefined || bare !== undefined) {
            const tok = stripWs(backticked !== undefined ? backticked : bare);
            if (/^[\w./@-]+\.md$/.test(tok) && !tok.includes("*")) {
              target = resolveMd(ROOT, d, tok) ?? tok;
              targetEnd = m.index + m[0].length;
              shadow = null;
            } else if (backticked !== undefined && /^[\w./@-]+$/.test(tok)) {
              shadow = tok;
              shadowEnd = m.index + m[0].length;
            } else {
              shadow = null;
            }
            continue;
          }
          const cited = stripWs(name);
          if (shadow !== null && m.index - shadowEnd <= 4
              && ADJACENT_RE.test(para.slice(shadowEnd, m.index))) {
            shadow = null;
            continue;
          }
          let targeted = false;
          let file = d;
          if (target !== null) {
            const gap = para.slice(targetEnd, m.index);
            if (ADJACENT_RE.test(gap) || CONNECTOR_RE.test(gap)) {
              file = target;
              targeted = true;
              targetEnd = m.index + m[0].length;
            } else {
              target = null;
            }
          }
          if (!targeted && !bareToo) continue;
          let aset = anchorsOf[file];
          if (aset === undefined) {
            if (!existsSync(join(ROOT, file))) continue;   // A1 owns a path that does not resolve
            aset = anchors(readText(join(ROOT, file)));
            anchorsOf[file] = aset;
          }
          if (!citesSection(aset, cited)) {
            findings.push(finding("A2", d, base + lineOf(para, m.index), `${file} § ${cited}`,
              `cites \`${file}\` § ${cited}, which names no heading there`));
          }
        }
        base += (para.match(/\n/g)?.length ?? 0) + 2;
      }
    }
  }

  // ── A3. The documented check list and CI name the same commands. ─────────
  if (on("A3")) {
    ran += 1;
    const localOnly = new Set(opt("A3", "local_only", []));
    const ciOnly = new Set(opt("A3", "ci_only", []));
    const extra = opt("A3", "extra_tokens", []);
    const documented = new Map();
    let scoped = true;
    for (const site of opt("A3", "doc_sections", [])) {
      const f = site.file;
      const name = site.section;
      if (!(f in textOf)) {
        findings.push(finding("A3", f, 1, name,
          `assertions.A3 names \`${f}\`, which is not a doc here — the comparison against CI `
          + `was not made`));
        scoped = false;
        continue;
      }
      const body = sectionBody(textOf[f], name);
      if (body === null) {
        findings.push(finding("A3", f, 1, name,
          `no section called § ${name} in \`${f}\` — the comparison against CI was not `
          + `made, which a renamed heading would otherwise do silently`));
        scoped = false;
        continue;
      }
      const blocks = [...body.matchAll(/```bash\n([\s\S]*?)```/g)].map((b) => b[1]);
      if (!blocks.length) {
        findings.push(finding("A3", f, 1, name,
          `§ ${name} in \`${f}\` has no \`\`\`bash block — the comparison against CI was `
          + `not made`));
        scoped = false;
        continue;
      }
      let joined = blocks.join("\n");
      for (const lit of localOnly) joined = joined.replaceAll(lit, "");
      const at = textOf[f].indexOf(name);
      for (const tok of checkTokens(joined, extra)) {
        if (!documented.has(tok)) documented.set(tok, [f, lineOf(textOf[f], at >= 0 ? at : 0)]);
      }
    }
    if (scoped) {
      const glob = opt("A3", "workflow_glob", ".github/workflows/*.yml");
      const workflows = globFiles(ROOT, glob);
      if (!workflows.length) {
        findings.push(finding("A3", glob, 1, "",
          "no workflow matches assertions.A3.workflow_glob — the comparison was not made. "
          + "Switch A3 off until CI exists; off is distinct from passing"));
      } else {
        const inCi = new Map();
        for (const rel of workflows) {
          for (const [lineNo, payload] of runPayloads(readText(join(ROOT, rel)))) {
            for (const tok of checkTokens(payload, extra)) {
              if (!inCi.has(tok)) inCi.set(tok, [rel, lineNo]);
            }
          }
        }
        for (const [tok, [f, ln]] of [...documented.entries()].sort((a, b) => cmp(a[0], b[0]))) {
          if (!inCi.has(tok) && !ciOnly.has(tok)) {
            findings.push(finding("A3", f, ln, tok,
              `\`${tok}\` is documented as a check but no CI step runs it`));
          }
        }
        for (const [tok, [f, ln]] of [...inCi.entries()].sort((a, b) => cmp(a[0], b[0]))) {
          if (!documented.has(tok) && !localOnly.has(tok)) {
            findings.push(finding("A3", f, ln, tok,
              `CI runs \`${tok}\` but no documented check list names it`));
          }
        }
      }
    }
  }

  // ── A4. Every `<identifier>.<field>` in prose resolves. ──────────────────
  if (on("A4")) {
    ran += 1;
    // A built-in default, because an empty list is not a sensible one: on a real repo it read
    // `jobs.py` and `apiaries.io` as table columns. `not_fields` ADDS to the default, so a repo
    // cannot lose it by naming one exemption of its own; `not_fields_override` replaces it
    // outright, for the repo whose column really is called `html`.
    const override = opt("A4", "not_fields_override", null);
    const notFields = override !== null
      ? new Set(override)
      : new Set([...DEFAULT_NOT_FIELDS, ...opt("A4", "not_fields", [])]);
    const notRefs = new Set(opt("A4", "not_references", []));
    const tables = {};
    for (const art of opt("A4", "artifacts", [])) {
      const p = join(ROOT, art.path);
      if (!existsSync(p)) {
        findings.push(finding("A4", art.path, 1, "",
          "assertions.A4 names this artifact, which is not in the repo — nothing was resolved "
          + "against it"));
        continue;
      }
      if (art.parser === "sql") Object.assign(tables, sqlTables(readText(p)));
      else if (art.parser === "ts") Object.assign(tables, tsUnions(readText(p)));
    }
    if (Object.keys(tables).length) {
      for (const d of docs) {
        for (const m of textOf[d].matchAll(/`(\w+)\.(\w+)`/g)) {
          const whole = m[0].replaceAll("`", "");
          const left = m[1];
          const right = m[2];
          // Object.hasOwn, not `in`: `constructor.name` passed through the prototype chain and
          // then dereferenced a non-Set — a hard crash here and a silent skip in Python, which is
          // exactly the divergence the two emissions are compared to prevent.
          if (notFields.has(right) || notRefs.has(whole) || !Object.hasOwn(tables, left)) continue;
          if (!tables[left].has(right)) {
            findings.push(finding("A4", d, lineOf(textOf[d], m.index), whole,
              `\`${whole}\` does not resolve: \`${left}\` has no \`${right}\`. The artifact is `
              + `authoritative`));
          }
        }
      }
    }
  }

  // ── A5. A vocabulary block names exactly the members the artifact defines. ──
  if (on("A5")) {
    ran += 1;
    for (const v of opt("A5", "vocabularies", [])) {
      const f = v.file;
      const name = v.section;
      if (!(f in textOf)) {
        findings.push(finding("A5", f, 1, name,
          `assertions.A5 names \`${f}\`, which is not a doc here`));
        continue;
      }
      const body = sectionBody(withoutStruck(textOf[f]), name);
      if (body === null) {
        findings.push(finding("A5", f, 1, name,
          `no section called § ${name} in \`${f}\` — the vocabulary was not compared`));
        continue;
      }
      const blocks = [...body.matchAll(/```[\w]*\n([\s\S]*?)```/g)].map((b) => b[1]);
      if (!blocks.length) {
        findings.push(finding("A5", f, 1, name,
          `§ ${name} in \`${f}\` has no fenced block — the vocabulary was not compared`));
        continue;
      }
      const stated = new Set(blocks.join("\n").split(/[ \t\r\n\f\v,]+/).filter(Boolean));
      let defined = null;
      // An A4 artifact list that is present and EMPTY is an answer: Python's `or` read it as
      // absent and fell through to the top-level one, and `??` does not, so the two read
      // different artifacts. Both now take the A4 list whenever it is there.
      for (const art of (opt("A4", "artifacts") ?? cfg.artifacts ?? [])) {
        const p = join(ROOT, art.path);
        if (!existsSync(p)) continue;
        if (art.parser === "sql") defined = sqlEnum(readText(p), v.enum);
        else if (art.parser === "ts") defined = tsUnions(readText(p))[v.enum] ?? null;
        if (defined !== null) break;
      }
      const at = lineOf(textOf[f], Math.max(textOf[f].indexOf(name), 0));
      if (defined === null) {
        findings.push(finding("A5", f, at, v.enum,
          `the artifact defines no vocabulary called \`${v.enum}\``));
        continue;
      }
      for (const extraMember of [...stated].filter((x) => !defined.has(x)).sort(cmp)) {
        findings.push(finding("A5", f, at, extraMember,
          `§ ${name} lists \`${extraMember}\`, which the artifact does not define`));
      }
      for (const missing of [...defined].filter((x) => !stated.has(x)).sort(cmp)) {
        findings.push(finding("A5", f, at, missing,
          `the artifact defines \`${missing}\`, which § ${name} does not list`));
      }
    }
  }

  // ── A6. A retired name never reappears. ─────────────────────────────────
  if (on("A6")) {
    ran += 1;
    for (const entry of opt("A6", "retired", [])) {
      // The boundaries are written out because a `\b` here is ASCII-only whatever the flags,
      // and `u` IS set, because without it JS folding is *narrower* than Python's `re.I`: `i`
      // alone excludes the Unicode-to-ASCII mappings, so U+017F LONG S and U+212A KELVIN SIGN
      // matched a retired ASCII name in Python and not here. Measured both ways; with `giu` the
      // two sides agree on those, `naïve` still matches "NAÏVE", and a name inside a longer
      // ASCII word still does not match.
      const rx = new RegExp("(?<![A-Za-z0-9_])"
        + entry.name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "(?![A-Za-z0-9_])", "giu");
      for (const d of docs) {
        for (const m of withoutStruck(textOf[d]).matchAll(rx)) {
          findings.push(finding("A6", d, lineOf(textOf[d], m.index), entry.name,
            `\`${entry.name}\` is retired — it became \`${entry.became ?? "?"}\` `
            + `(${entry.reason ?? "no reason recorded"})`));
        }
      }
    }
  }

  // ── A7. A reversed decision is not prescribed again. ────────────────────
  if (on("A7")) {
    ran += 1;
    for (const entry of opt("A7", "reversed", [])) {
      const rx = new RegExp(entry.pattern, "g");
      for (const d of docs) {
        for (const m of withoutStruck(textOf[d]).matchAll(rx)) {
          const where = entry.adr ?? "the decision record";
          findings.push(finding("A7", d, lineOf(textOf[d], m.index), m[0],
            `prescribes a reversed decision: ${entry.reason} — see \`${where}\``));
        }
      }
    }
  }

  // ── A8. One issue, one owning plan. ─────────────────────────────────────
  if (on("A8")) {
    ran += 1;
    const rawGlobs = opt("A8", "plan_glob", "docs/plans/*.md");
    const globList = typeof rawGlobs === "string" ? [rawGlobs] : [...rawGlobs];
    const res = globList.map(globRe);
    // Enabled and matching nothing is not a pass. Same rule A3 and A12 follow: an assertion that
    // cannot make its comparison says so, because silence reads as evidence.
    const plans = docs.filter((d) => res.some((rx) => rx.test(d)));
    if (!plans.length) {
      findings.push(finding("A8", CONFIG_PATH, 1, globList.join(", "),
        `assertions.A8 is enabled and \`${globList.join(", ")}\` matches no doc — the `
        + `one-issue-one-plan comparison was not made. Point it at the layer-5 rows, or switch `
        + `A8 off; off is distinct from passing`));
    }
    const owners = new Map();
    for (const d of plans) {
      const span = sectionSpan(textOf[d], "The issues");
      if (span === null) continue;
      const [body, base] = span;
      for (const [i, cells] of tableRows(body)) {
        // `\p{Nd}` under `u`, deliberately: ASCII here narrowed toward SILENCE, and a numbered
        // row in another script is still a numbered row.
        if (cells.length < 2 || !/^~*\p{Nd}+~*$/u.test(cells[0])) continue;
        const m = cells[1].match(/#(\d+)/);
        if (m) {
          if (!owners.has(m[1])) owners.set(m[1], []);
          owners.get(m[1]).push([d, base + i]);
        }
      }
    }
    for (const [issue, places] of [...owners.entries()].sort((a, b) => Number(a[0]) - Number(b[0]))) {
      if (new Set(places.map((p) => p[0])).size > 1) {
        const where = [...new Set(places.map((p) => p[0]))].sort(cmp).join(", ");
        // An explicit comparator, because the default one stringifies the pair: `["f", 10]`
        // sorts before `["f", 9]` as text, and Python compares the line as a number.
        for (const [f, ln] of places.slice().sort((a, b) => cmp(a[0], b[0]) || a[1] - b[1])) {
          findings.push(finding("A8", f, ln, "#" + issue,
            `#${issue} is owned by more than one plan (${where}) — one issue, one owning plan, `
            + `so "where is this tracked" has one answer`));
        }
      }
    }
  }

  // ── A9. A stated count matches a computed one. ──────────────────────────
  if (on("A9")) {
    ran += 1;
    for (const site of opt("A9", "count_sites", [])) {
      const rx = new RegExp(site.pattern, "g");
      const actual = globFiles(ROOT, site.count_of).length;
      const targets = site.file ? [site.file] : docs;
      for (const d of targets) {
        if (!(d in textOf)) continue;
        for (const m of withoutStruck(textOf[d]).matchAll(rx)) {
          const word = m[1];
          const stated = asciiInt(word) ?? WORDS[word.toLowerCase()];
          if (stated === undefined || stated === actual) continue;
          findings.push(finding("A9", d, lineOf(textOf[d], m.index), m[0],
            `states ${word} (${stated}) where \`${site.count_of}\` matches ${actual}`));
        }
      }
    }
  }

  // ── A10. Every doc under docs/ is in the table, with a layer. ───────────
  if (on("A10")) {
    ran += 1;
    if (!(host in textOf)) {
      findings.push(finding("A10", host, 1, "",
        `\`${host}\` hosts the sources-of-truth table and is not in the repo`));
    } else if (!table.length) {
      findings.push(finding("A10", host, 1, "",
        `no sources-of-truth table found in \`${host}\` — every doc is unowned until there is one`));
    } else {
      const patterns = table.map((r) => [globRe(r.doc), r]);
      for (const d of docs) {
        if (!d.startsWith("docs/")) continue;
        const hit = patterns.find(([rx]) => rx.test(d));
        const row = hit ? hit[1] : null;
        if (row === null) {
          findings.push(finding("A10", d, 1, d,
            `\`${d}\` is under docs/ and has no row in \`${host}\` — a doc in the table or it is `
            + `drift, there is no third state`));
        } else if (row.layer === null) {
          findings.push(finding("A10", host, row.line, row.doc,
            `the row for \`${row.doc}\` has no layer — the layer is what fixes the edit rule and `
            + `selects the assertions`));
        } else if (!(row.layer in LAYER_NAMES)) {
          findings.push(finding("A10", host, row.line, row.doc,
            `the row for \`${row.doc}\` says layer ${row.layer}, which is not 1..6`));
        }
      }
    }
  }

  // ── A11. Config `load_bearing` and the table's Enforces column agree. ──
  if (on("A11")) {
    ran += 1;
    const loadBearing = cfg.load_bearing ?? [];
    const globs = loadBearing.map(globRe);
    for (const row of table) {
      const e = stripWs(row.enforces);
      if (!e) continue;
      // A path-shaped value is held to `load_bearing`; a command is not. An Enforces cell may
      // name "a constraint, an index, a CI assertion", and a CI assertion is a command — which
      // `load_bearing` must not carry, because the review policy and the follow-up qualifier read
      // that list as path globs.
      if (e.includes(" ") || !/[/.]/.test(e)) continue;
      if (!globs.some((rx) => rx.test(e)) && !loadBearing.includes(e)) {
        findings.push(finding("A11", host, row.line, e,
          `the row for \`${row.doc}\` says it is enforced by \`${e}\`, which is not on `
          + `\`load_bearing\` in ${CONFIG_PATH} — the two copies of what carries weight have `
          + `drifted`));
      }
    }
    // The layer exists in the table and in the config. Nothing read the config's copy, so a doc's
    // layer could be two different things with nothing reconciling them — which is the exact
    // failure the method's central rule exists to prevent.
    const byPath = new Map(table.map((r) => [r.doc, r]));
    for (const d of cfg.docs ?? []) {
      // Read once, through `??`: a null printed as `null` here and as `None` there, and the
      // message is part of a finding's baseline key.
      const path = d.path ?? "";
      const layer = d.layer ?? "";
      const row = byPath.get(path);
      if (row === undefined) {
        findings.push(finding("A11", CONFIG_PATH, 1, path,
          `${CONFIG_PATH} lists \`${path}\` and \`${host}\` has no row for it`));
      } else if (row.layer !== null && layer !== row.layer) {
        findings.push(finding("A11", host, row.line, path,
          `\`${path}\` is layer ${row.layer} in the table and layer ${layer} in `
          + `${CONFIG_PATH} — the layer fixes the edit rule, so two answers is two edit rules`));
      }
    }
  }

  // ── A12. Append-only layers are byte-frozen on the default branch. ─────
  //
  // One exception, for one file: a single dated decisions file is a record that is appended to by
  // design, so byte-equality would make it impossible to append to. For that path alone the
  // branch's bytes must be an unbroken PREFIX of the working copy. Bytes, not decoded text: a
  // decode would let invalid UTF-8 compare differently here than in the Python checker.
  if (on("A12")) {
    ran += 1;
    // Unset, or null, means the repo's own default branch. Anything else must be a branch name:
    // a `true` printed as `true` here and as `True` in the other language, and the finding's text
    // is part of its baseline key, so one config had two keys. A15 was given this treatment and
    // A12 was not; it is one pattern, not one site.
    const rawBranch = [opt("A12", "default_branch"), cfg.repo?.default_branch]
      .find((v) => v !== undefined && v !== null) ?? "main";
    const validBranch = typeof rawBranch === "string" && rawBranch !== "";
    const branch = validBranch ? rawBranch : "";
    const adrCfg = cfg.adr ?? {};
    const appendOnly = adrCfg.format === "single" ? (adrCfg.file ?? "docs/decisions.md") : null;
    // The same directory and the same test for "a MADR record" that A13 uses.
    const madrDir = adrCfg.format === "madr" ? (adrCfg.dir ?? "docs/adr") : null;
    const frozen = table.filter((r) => r.layer === 3 || r.layer === 4).map((r) => globRe(r.doc));
    const ref = validBranch ? resolveDefaultBranch(branch) : null;
    if (!validBranch) {
      findings.push(finding("A12", CONFIG_PATH, 1, "default_branch",
        `assertions.A12.default_branch is not a branch name — the byte-freeze comparison was not `
        + `made. Set it to a string naming the default branch, or switch A12 off; off is distinct `
        + `from passing`));
    } else if (ref === null) {
      findings.push(finding("A12", CONFIG_PATH, 1, branch,
        `no branch called \`${branch}\` and no \`origin/${branch}\` — the byte-freeze comparison `
        + `was not made. Fetch the branch (in CI, \`fetch-depth: 0\` and the default branch `
        + `fetched), set assertions.A12.default_branch, or switch A12 off; off is distinct from `
        + `passing`));
    } else {
      for (const d of docs) {
        if (!frozen.some((rx) => rx.test(d)) || !frozenRecord(d)) continue;
        let was;
        try {
          was = execFileSync("git", ["show", `${ref}:${d}`],
            { cwd: ROOT, stdio: ["ignore", "pipe", "ignore"] });
        } catch { continue; }       // not on the branch yet: a new record, which is the point
        const now = readFileSync(join(ROOT, d));
        const layer = table.find((r) => globRe(r.doc).test(d)).layer;
        if (d === appendOnly) {
          if (now.length < was.length || !now.subarray(0, was.length).equals(was)) {
            findings.push(finding("A12", d, 1, d,
              `is layer ${layer} (${LAYER_NAMES[layer]}), append-only, and already on `
              + `\`${ref}\`: what is there must stay, byte for byte, at the top of this file. `
              + `An entry was edited, not appended. A reversal is a new dated entry; a correction `
              + `is not available here`));
          }
        } else if (!was.equals(now)) {
          const madr = madrDir !== null && d.startsWith(madrDir + "/");
          if (madr && differsOnlyInStatusLines(was, now)) continue;
          findings.push(finding("A12", d, 1, d,
            `is layer ${layer} (${LAYER_NAMES[layer]}) and already on \`${ref}\`, so its `
            + `bytes are final. A reversal is a new entry; a correction is not available here`
            + (madr ? ". Only its **Status:** line may change, to name what superseded it" : "")));
        }
      }
    }
  }

  // ── A13. The append-only layers keep their shape. ──────────────────────
  if (on("A13")) {
    ran += 1;
    const adr = cfg.adr ?? {};
    if (adr.format === "madr") {
      const dDir = adr.dir ?? "docs/adr";
      for (const d of docs) {
        if (!d.startsWith(dDir + "/")) continue;
        if (basename(d) === "README.md" || basename(d) === "template.md") continue;
        const text = textOf[d];
        if (!/^\*\*Date:\*\*/m.test(text)) {
          findings.push(finding("A13", d, 1, "Date",
            "a decision record carries a **Date:** — without one, \"what was decided when\" has "
            + "no answer and the append-only rule has nothing to anchor to"));
        }
        const m = text.match(/^\*\*Status:\*\*[ \t]*(.*)$/m);
        if (!m) {
          findings.push(finding("A13", d, 1, "Status",
            "a decision record carries a **Status:** — proposed, accepted, or superseded by NNNN"));
        } else if (m[1].toLowerCase().includes("superseded")) {
          const succ = m[1].match(/superseded by\s+(\d{4})/i);
          if (!succ) {
            findings.push(finding("A13", d, lineOf(text, m.index), m[1],
              "a superseded record names its successor by number, or the reversal is unfindable"));
          } else if (!globFiles(ROOT, `${dDir}/${succ[1]}-*.md`).length) {
            findings.push(finding("A13", d, lineOf(text, m.index), succ[1],
              `names ${succ[1]} as its successor, and there is no such record`));
          }
        }
      }
    } else {
      const f = adr.file ?? "docs/decisions.md";
      if (f in textOf) {
        for (const m of textOf[f].matchAll(/^##[ \t]+(.*)$/gm)) {
          const after = textOf[f].slice(m.index + m[0].length, m.index + m[0].length + 400);
          if (!/\d{4}-\d{2}-\d{2}/.test(after.split("\n##")[0])) {
            findings.push(finding("A13", f, lineOf(textOf[f], m.index), m[1],
              "a dated decisions file gives every entry a date — the layer is append-only and "
              + "dated, and the date is what makes it a record"));
          }
        }
      }
    }
    const prdDir = cfg.prd?.dir ?? "docs/prd";
    const index = `${prdDir}/README.md`;
    if (index in textOf) {
      for (const d of docs) {
        const base = basename(d);
        // `\p{Nd}`: A13 exists so an unindexed version cannot hide, and `PRD-v٣.md` was
        // invisible to both checkers while this was ASCII.
        if (!d.startsWith(prdDir + "/") || !/^PRD-v\p{Nd}+\.md$/u.test(base)) continue;
        // Findable by filename or by version label: an index row reading `| v0 | … |` makes the
        // version perfectly findable, and A13 exists so an unindexed version cannot hide, not so
        // the index has to spell a filename.
        const label = base.slice(4, -3);                 // PRD-v0.md -> v0
        const byLabel = new RegExp("(?<![\\w-])" + label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
          + "(?![\\w.-])");
        if (!textOf[index].includes(base) && !byLabel.test(textOf[index])) {
          findings.push(finding("A13", index, 1, base,
            `\`${base}\` is a PRD version and is named nowhere in the index — neither as the `
            + `filename nor as \`${label}\`. An unindexed version is one nobody can find`));
        }
      }
    } else if (docs.some((d) => d.startsWith(prdDir + "/"))) {
      findings.push(finding("A13", index, 1, "",
        `\`${prdDir}/\` has versions and no \`README.md\` index`));
    }
  }

  // ── A14. The units table has the shape it claims. ──────────────────────
  if (on("A14")) {
    ran += 1;
    const rawGlobs = opt("A14", "plan_glob", "docs/plans/*.md");
    const globList = typeof rawGlobs === "string" ? [rawGlobs] : [...rawGlobs];
    const res = globList.map(globRe);
    // Enabled and matching nothing is not a pass: the same rule A8 follows.
    const plans = docs.filter((d) => res.some((rx) => rx.test(d)));
    if (!plans.length) {
      findings.push(finding("A14", CONFIG_PATH, 1, globList.join(", "),
        `assertions.A14 is enabled and \`${globList.join(", ")}\` matches no doc — the units `
        + `comparison was not made. Point it at the layer-5 rows, or switch A14 off; off is `
        + `distinct from passing`));
    }
    // What counts as an assertion is the repo's to say: a Go table test fails through `t.Fatalf`
    // and contains no assertion word at all, so no default can be right for every repo. A pattern
    // that cannot be read the same way by both checkers is reported, and only the comparison
    // that needed it is skipped.
    const pat = opt("A14", "assertion_pattern", DEFAULT_ASSERTION_PATTERN);
    let assertRe = null;
    let why = typeof pat === "string" ? portableRegex(pat) : "it is not a string";
    if (why === null) {
      try { assertRe = new RegExp(pat, "m"); } catch { why = "it did not compile"; }
    }
    if (why !== null) {
      findings.push(finding("A14", CONFIG_PATH, 1, typeof pat === "string" ? pat : "",
        `assertions.A14.assertion_pattern${typeof pat === "string" ? ` \`${pat}\`` : ""} could not `
        + `be compiled — ${why}. Whether a test file asserts anything was not compared; the rest `
        + `of A14 ran. Write the pattern in the subset \`references/assertions.md\` § A14 `
        + `describes, or remove the key for the default`));
    }
    for (const d of plans) {
      const text = textOf[d];
      const span = sectionSpan(text, "The units");
      if (span === null) {
        // Only a plan that sequences issues is a plan that owes its units. A layer-5 doc with
        // neither section is another kind of file under the same glob, and says nothing here.
        if (sectionBody(text, "The issues") !== null) {
          findings.push(finding("A14", d, 1, "The units",
            "has a `§ The issues` and no `§ The units` — the units comparison was not made. A "
            + "plan names its units, each with the test that proves it, or nothing says what "
            + "\"done\" is"));
        }
        continue;
      }
      // Both from the scan: `text.indexOf(body)` is a lookup by content, and a plan that quotes
      // its own units table has those exact lines earlier in the file.
      const [body, base] = span;
      let units = 0;
      for (const [i, cells] of tableRows(body)) {
        // A bare numeral only: the header, the rule under it, and a struck-through unit are not
        // units, so none of them is held to the shape.
        // `\p{Nd}`, as in A8's row test and for the same reason.
        if (!/^\p{Nd}+$/u.test(cells[0])) continue;
        units += 1;
        const proves = cells[2] ?? "";
        const m = proves.match(/^`([\w./-]+)`$/);
        if (!m) {
          findings.push(finding("A14", d, base + i, proves,
            `unit ${cells[0]} has no test path in its "Proves it" cell — a unit is the smallest `
            + `piece of work that carries its own test, so name the test as a backticked path`));
          continue;
        }
        // Only a plain repo-relative file path is read. An absolute one resolves differently in
        // the two languages (pathlib's `/` replaces the root, join concatenates onto it), a
        // trailing `/` does too (pathlib drops it, so the file is found; a stat in Node fails
        // with ENOTDIR), and `..` leaves the repo, which a repo's own check has no business
        // reading.
        if (m[1].startsWith("/") || m[1].endsWith("/") || m[1].split("/").includes("..")) {
          findings.push(finding("A14", d, base + i, m[1],
            `unit ${cells[0]} names \`${m[1]}\` as its test, and that is not a file path inside `
            + `the repo — write it relative to the repo root, with no leading \`/\`, no trailing `
            + `\`/\` and no \`..\``));
          continue;
        }
        // A file that is there and cannot be opened is not a missing one, and it must not take
        // the checker down: every assertion after this one would stop running, and a crash exits
        // nonzero, which looks the same as findings.
        let state = "ok";
        let content = "";
        try {
          const tp = join(ROOT, m[1]);
          if (statSync(tp).isFile()) content = readText(tp);
          else state = "missing";
        } catch (e) {
          state = e.code === "ENOENT" || e.code === "ENOTDIR" ? "missing" : "unreadable";
        }
        if (state === "missing") {
          findings.push(finding("A14", d, base + i, m[1],
            `unit ${cells[0]} names \`${m[1]}\` as its test, and there is no such file`));
        } else if (state === "unreadable") {
          findings.push(finding("A14", d, base + i, m[1],
            `unit ${cells[0]} names \`${m[1]}\` as its test, and the file could not be read — `
            + `whether it asserts anything was not compared`));
        } else if (assertRe !== null) {
          // The pattern sees the file with line endings made `\n` and each run of non-ASCII
          // characters made one `~`, so `.`, `\s` and `$` mean the same to both engines.
          const flat = content.replace(/[^\x00-\x7f]+/g, "~");
          if (!assertRe.test(flat)) {
            findings.push(finding("A14", d, base + i, m[1],
              `unit ${cells[0]} names \`${m[1]}\` as its test, and the file asserts nothing — `
              + `nothing in it matches \`assertions.A14.assertion_pattern\``));
          }
        }
      }
      // A heading with nothing under it compared nothing, which is the missing section again.
      if (units === 0) {
        findings.push(finding("A14", d, 1, "The units",
          "has a `§ The units` with no unit in it — the units comparison was not made. A unit is "
          + "a numbered row naming the test that proves it; a struck-through row is not one"));
      }
    }
  }

  // ── A15. A test arrives before the implementation it proves. ───────────
  //
  // Off by default: it needs two repo-specific lists. Reads the commits this branch has and the
  // default branch has not, oldest first, and holds the files ADDED in them to the order a
  // test-first method promises. A finding names the implementation file, line 1 — never a commit,
  // because a sha is fresh on every branch and a finding carrying one could not be baselined.
  if (on("A15")) {
    // Unset, or null, means the repo's own default branch. Anything else must be a branch name:
    // a `true` would print as `true` here and `True` in the other language, and the finding's text
    // is part of its baseline key.
    const rawBranch = [opt("A15", "default_branch"), cfg.repo?.default_branch]
      .find((v) => v !== undefined && v !== null) ?? "main";
    const validBranch = typeof rawBranch === "string" && rawBranch !== "";
    const branch = validBranch ? rawBranch : "";
    const globsOf = (k) => {
      const v = opt("A15", k, []);
      return (typeof v === "string" ? [v] : Array.isArray(v) ? v : [])
        .filter((g) => typeof g === "string" && g !== "");
    };
    const implGlobs = globsOf("impl_globs");
    const testGlobs = globsOf("test_globs");
    // Every way git can fail — a branch that is not there, a shallow clone, no git at all — is
    // null, because each means the same thing here: the comparison cannot be made.
    const git = (...args) => {
      try {
        return execFileSync("git", args, { cwd: ROOT, encoding: "utf8", maxBuffer: 1 << 30,
          stdio: ["ignore", "pipe", "ignore"] });
      } catch { return null; }
    };
    // The local branch, else `origin/<branch>`: see resolveDefaultBranch. `branch` stays the
    // finding's text, so a baseline entry is keyed on the configured name whichever form resolved.
    const ref = validBranch ? resolveDefaultBranch(branch) : null;
    const unreadable = [branch,
      `git could not read the commits in \`${ref}..HEAD\` — the test-first comparison was `
      + `not made. Switch A15 off if this checkout cannot be given its history; off is distinct `
      + `from passing`];
    let notMade = null;      // [text, message] when the comparison cannot be made
    let walked = false;      // whether the range held a commit at all
    const late = [];         // implementation files added before any test
    if (!implGlobs.length || !testGlobs.length) {
      const empty = [implGlobs.length ? null : "impl_globs", testGlobs.length ? null : "test_globs"]
        .filter((k) => k !== null);
      notMade = [empty.join(", "),
        `assertions.A15 is enabled with nothing in ${empty.map((k) => `\`${k}\``).join(" and ")} — `
        + `the test-first comparison was not made. A15 compares the paths that are implementation `
        + `with the paths that are tests, so it needs both. Fill them in, or switch A15 off; off is `
        + `distinct from passing`];
    } else if (!validBranch) {
      notMade = ["default_branch",
        `assertions.A15.default_branch is not a branch name — the test-first comparison was not `
        + `made. Set it to a string naming the default branch, or switch A15 off; off is distinct `
        + `from passing`];
    } else if (ref === null) {
      notMade = [branch,
        `git cannot resolve \`${branch}\` or \`origin/${branch}\` to a commit — the test-first `
        + `comparison was not made. Fetch the branch (in CI, \`fetch-depth: 0\` and the default `
        + `branch fetched), set assertions.A15.default_branch, or switch A15 off; off is distinct `
        + `from passing`];
    } else if (git("merge-base", ref, "HEAD") === null) {
      // A shallow clone cuts the history off, so git shows every file in the oldest commit it has
      // as added by it. Comparing that would be comparing nothing.
      notMade = [branch,
        `HEAD and \`${ref}\` share no history git can see (a shallow clone is the usual cause), `
        + `so which commits are this branch's is unknown and the test-first comparison was not `
        + `made. Fetch the full history (in CI, \`fetch-depth: 0\`), or switch A15 off; off is `
        + `distinct from passing`];
    } else {
      // Merges are skipped: what a merge brings in is either on the default branch already, and so
      // outside the range, or another branch's commits, which the range lists in their own right.
      const listed = git("rev-list", "--reverse", "--topo-order", "--no-merges", `${ref}..HEAD`);
      if (listed === null) notMade = unreadable;
      const shas = (listed ?? "").split("\n").filter((x) => x !== "");
      walked = shas.length > 0;
      const testRes = testGlobs.map(globRe);
      const implRes = implGlobs.map(globRe);
      const isTest = (p) => testRes.some((rx) => rx.test(p));
      const isImpl = (p) => implRes.some((rx) => rx.test(p));
      let seenTest = false;
      for (const sha of shas) {
        // Once a test has arrived nothing after it can be early, so the walk only goes on for a
        // file still outstanding: it has to be followed through a later rename, or it would be
        // dropped as gone.
        if (seenTest && late.length === 0) break;
        // `-z` so a path with a space or a non-ASCII character is not quoted, `-M` so a rename is
        // told from a new file, `-l` so the repo's `diff.renameLimit` cannot turn a batch of
        // renames back into new files, `--relative` so a checker below the repo root sees its
        // own paths. Plumbing, because `git show` obeys the user's config and diff-tree mostly
        // does not.
        const out = git("diff-tree", "--no-commit-id", "--root", "-r", "-z", "-M", "-l32767",
          "--relative", "--name-status", sha);
        if (out === null) { notMade = unreadable; break; }
        const added = [];
        const moved = [];
        const toks = out.split("\0");
        for (let i = 0; i < toks.length && toks[i] !== "";) {
          // A rename or copy entry carries two paths. Neither is an arrival.
          if (/^[RC]/.test(toks[i])) {
            if (toks[i][0] === "R") moved.push([toks[i + 1], toks[i + 2]]);
            i += 3;
            continue;
          }
          if (toks[i] === "A") added.push(toks[i + 1]);
          i += 2;
        }
        // A rename is not a delete: an outstanding file is still in the tree under its new name,
        // as long as that name is still an implementation path, and not a test one: a path
        // matching both lists is a test, as it is where a file is added.
        for (const [from, to] of moved) {
          const k = late.indexOf(from);
          if (k < 0) continue;
          late.splice(k, 1);
          if (isImpl(to) && !isTest(to) && !late.includes(to)) late.push(to);
        }
        if (seenTest) continue;
        // Tests are checked before implementations, so a file matching both lists is a test:
        // read as an implementation, a test beside the code it proves would be its own missing
        // test.
        if (added.some(isTest)) { seenTest = true; continue; }
        for (const p of added.filter(isImpl)) if (!late.includes(p)) late.push(p);
      }
    }
    if (notMade !== null) {
      ran += 1;
      findings.push(finding("A15", CONFIG_PATH, 1, notMade[0], notMade[1]));
    } else if (!walked) {
      // After a squash merge a test and its implementation are always one commit, so on the
      // default branch this check has nothing to compare. Saying so is not a finding, and silence
      // would read as a pass. It is counted: A15 ran and reached a verdict, and a total that
      // differed between branches for one config would say nothing about the config.
      ran += 1;
      process.stdout.write(`A15: not applicable on ${ref} — a squash merge puts test and `
        + `implementation in one commit\n`);
    } else {
      ran += 1;
      // A file the branch added and later removed is not in the tree at HEAD: there is nothing to
      // open and nothing to fix, and it proves nothing. `HEAD:./` is relative to where the checker
      // runs, like the paths above.
      for (const p of late.filter((q) => git("cat-file", "-e", `HEAD:./${q}`) !== null)) {
        findings.push(finding("A15", p, 1, p,
          `is an implementation file (\`assertions.A15.impl_globs\`) added in \`${ref}..HEAD\` `
          + `with no test (\`assertions.A15.test_globs\`) before it or in the same commit — a test `
          + `arrives before, or with, the implementation it proves. Reorder the commits so a test `
          + `comes first, or put one in the commit that adds this file`));
      }
    }
  }

  // ── A16. The config is the projection of the answers file. ─────────────
  //
  // The answers file is the source and the config is its projection, so the config is never
  // hand-edited. What is compared is **two whole-file hashes the wizard recorded at projection
  // time**, not the projection re-derived here: this script is emitted in two languages and
  // cannot import the wizard, so re-deriving would mean a second and a third copy of the one
  // function this whole layer exists to keep single.
  //
  // Two hashes, because they catch opposite directions and only one of them is the bug this
  // assertion is for. The ANSWERS hash catches a source that moved with nothing regenerated after
  // it — a stale config. The CONFIG hash catches a config edited directly, which an answers hash
  // cannot see at all, because editing the config leaves the answers file untouched.
  if (on("A16")) {
    ran += 1;
    const hex = (v) => typeof v === "string" && /^[0-9a-f]{64}$/.test(v);
    // A file that is there and cannot be opened is not a missing one, and it must not take the
    // checker down: the same rule A14 follows for a unit's test file.
    const sha = (rel) => {
      try { return createHash("sha256").update(readFileSync(join(ROOT, rel))).digest("hex"); }
      catch { return null; }
    };
    const regen = `Put the change in the answers file and regenerate`
      + ` (\`seam-init --answers <file> --repo .\`), which rewrites ${CONFIG_PATH} from it`;
    // `prov` is a readable object here, or the integrity precondition above refused the run: a
    // config with no record of what it enabled is not a config this checker trusts at all.
    if (typeof prov.answers !== "string" || prov.answers === "") {
      findings.push(finding("A16", PROVENANCE_PATH, 1, "answers",
        `\`${PROVENANCE_PATH}\` names no answers file inside this repo, so the comparison was `
        + `not made — an answers file kept outside the tree cannot be read back from here. Commit `
        + `it and regenerate, or switch A16 off; off is distinct from passing`));
    } else if (!existsSync(join(ROOT, prov.answers))) {
      findings.push(finding("A16", PROVENANCE_PATH, 1, prov.answers,
        `names \`${prov.answers}\` as the answers file this config was projected from, and there `
        + `is no such file — the comparison was not made. Restore it and regenerate, or switch `
        + `A16 off; off is distinct from passing`));
    } else if (!hex(prov.answers_sha256) || !hex(prov.config_sha256)) {
      findings.push(finding("A16", PROVENANCE_PATH, 1, "sha256",
        `\`${PROVENANCE_PATH}\` carries no usable sha256 hash for the answers file and the `
        + `config, so neither was compared. Regenerate to record both, or switch A16 off; off is `
        + `distinct from passing`));
    } else {
      const ansHash = sha(prov.answers);
      const cfgHash = sha(CONFIG_PATH);
      for (const [rel, got] of [[prov.answers, ansHash], [CONFIG_PATH, cfgHash]]) {
        if (got !== null) continue;
        findings.push(finding("A16", rel, 1, rel,
          `could not be read, so its hash was not compared with the one `
          + `\`${PROVENANCE_PATH}\` records`));
      }
      if (ansHash !== null && ansHash !== prov.answers_sha256) {
        findings.push(finding("A16", prov.answers, 1, prov.answers,
          `has changed since ${CONFIG_PATH} was projected from it, so the config is stale: it is `
          + `the projection of an earlier version of this file. ${regen}`));
      }
      if (cfgHash !== null && cfgHash !== prov.config_sha256) {
        findings.push(finding("A16", CONFIG_PATH, 1, CONFIG_PATH,
          `was edited after it was emitted. The answers file is the source and this file is its `
          + `projection, so an edit here is reverted by the next regeneration without a word — `
          + `which has happened. ${regen}`));
      }
    }
  }

  // ── Repo-invented assertions. Discovered, never overwritten. ───────────
  const adir = join(ROOT, ".seam", "assertions");
  if (existsSync(adir) && statSync(adir).isDirectory()) {
    const ctx = { root: ROOT, config: cfg, docs, text_of: textOf, table, host };
    for (const f of readdirSync(adir).filter((x) => x.endsWith(".mjs")).sort(cmp)) {
      const mod = await import(pathToFileURL(join(adir, f)).href);
      if (typeof mod.run !== "function") {
        process.stderr.write(`seam: ${f} has no run(ctx)\n`);
        continue;
      }
      ran += 1;
      for (const r of (await mod.run(ctx)) ?? []) {
        findings.push(finding(r.id, r.file, Number(r.line), r.text ?? "", r.message));
      }
    }
  }

  // ── The baseline ───────────────────────────────────────────────────────
  const bpath = join(ROOT, cfg.baseline?.path ?? ".seam/baseline.json");
  const key = (f) => JSON.stringify([f.id, f.file, f.line, f.text]);
  // `cmp`, not `localeCompare`: a collation puts `alpha.md` before `Zeta.md` and Python's
  // code-point sort puts it after, so the two checkers printed the same findings in different
  // orders — and the order is what a human reads down. The baseline is a set and was unaffected,
  // which is why a green suite never saw this.
  findings.sort((a, b) =>
    cmp(a.id, b.id) || cmp(a.file, b.file) || a.line - b.line || cmp(a.text, b.text));

  if (process.argv.includes("--write-baseline")) {
    mkdirSync(dirname(bpath), { recursive: true });
    writeFileSync(bpath, JSON.stringify({
      seam_version: SEAM_VERSION,
      note: "Day-one drift, recorded so the checker fails only on what is new. A debt with a "
        + "number on it, not an approval: an entry here is expected to go away.",
      entries: findings.map((f) => ({ id: f.id, file: f.file, line: f.line, text: f.text })),
    }, null, 2) + "\n");
    process.stdout.write(`seam ${SEAM_VERSION}: baselined ${findings.length} violation(s) into `
      + `${relative(ROOT, bpath).split(sep).join("/")}\n`);
    return 0;
  }

  const baselined = new Set();
  if (existsSync(bpath)) {
    for (const e of (JSON.parse(readText(bpath)).entries ?? [])) {
      baselined.add(JSON.stringify([e.id, e.file, e.line, e.text ?? ""]));
    }
  }
  const fresh = findings.filter((f) => !baselined.has(key(f)));
  const carried = findings.length - fresh.length;

  process.stdout.write(`seam ${SEAM_VERSION}: ${ran} assertions, ${docs.length} docs, `
    + `${fresh.length} violations (${carried} baselined)\n`);
  if (!fresh.length) return 0;
  for (const f of fresh) {
    process.stderr.write(`${f.file}:${f.line}: ${f.id} ${f.message}\n`);
  }
  process.stderr.write(`\n${fresh.length} violation(s) outside the baseline. The artifact is `
    + `authoritative, and a lower layer cites a higher one rather than restating it: fix the `
    + `doc, or if the change was deliberate, change what enforces it in the same commit.\n`);
  return 1;
}

process.exit(await main());
